/**
 * What a bundle restores.
 */
data class RestoredBackup (
    var `spendKeyHex`: kotlin.String, 
    var `restoreHeight`: kotlin.ULong, 
    var `personaSecret`: kotlin.ByteArray, 
    var `displayName`: kotlin.String?, 
    var `publishPayto`: kotlin.Boolean, 
    /**
     * §16.9's profile, restored with everything else. A persona that comes
     * back without its face and its pronouns is not the same person to anyone
     * who knew them.
     */
    var `profile`: Profile, 
    var `contacts`: List<ContactBackup>, 
    var `prekeySignedSecret`: kotlin.ByteArray?, 
    var `prekeyOneTime`: List<PrekeyEntry>, 
    var `prekeyNextId`: kotlin.ULong, 
    var `appState`: kotlin.ByteArray?, 
    /**
     * Escrow shares carried in the bundle (§4.3.3). Zero is the normal case.
     */
    var `escrowCount`: kotlin.UInt, 
    /**
     * The shares themselves. This used to be the count alone, which told a
     * restoring device how much it had just failed to restore.
     */
    var `escrowShares`: List<EscrowShareEntry>, 
    /**
     * The persona roster, when the bundle carries one (post-1.0
     * compartments). Empty for older bundles: the top-level persona secret
     * is the only identity, exactly as it always was.
     */
    var `personas`: List<PersonaBackup>, 
    /**
     * When the bundle was written, in seconds since the epoch — the thing that
     * makes "how old is this backup" answerable.
     *
     * Carried across the bridge rather than kept inside, because §4.3.3's
     * escrow shares are the one part of a bundle that goes out of date, and
     * the client that has to say so is the one with the screen. Zero means the
     * bundle predates the export that started stamping this, and a caller must
     * read it as *unknown* rather than as 1970: a file of unknown age is not a
     * stale one, and refusing it, or nagging about it, would be a lie about a
     * perfectly good backup.
     */
    var `created`: kotlin.ULong
) {
    
    companion object
}

